const req = indexedDB.open("BoutiqueDB", 1);

req.onupgradeneeded = (e) => {
  const db = req.result;
  if (!db.objectStoreNames.contains("articles")) {
    const store = db.createObjectStore("articles", { keyPath: "id" });
    store.createIndex("titre", "titre", { unique: false });
  }
};

req.onsuccess = () => {
  const db = req.result;
  // 2. Transaction manuelle
  const tx = db.transaction("articles", "readwrite");
  const store = tx.objectStore("articles");

  // 3. Callback d'ajout
  const addReq = store.add({ id: "1", titre: "Livre" });
  addReq.onsuccess = () => {
    // 4. Callback de lecture
    const getReq = store.get("1");
    getReq.onsuccess = () => console.log(getReq.result);
    getReq.onerror = (err) => console.error(err);
  };
  addReq.onerror = (err) => console.error(err);
};
req.onerror = (err) => console.error(err);`),g()()(),m(185,"div",48)(186,"div",45),de(187,"span",49),m(188,"span"),f(189,"Dexie.js 4+ (4 lignes \xE9l\xE9gantes, typ\xE9es et async/await)"),g()(),m(190,"pre",47)(191,"code"),f(192,`// 1. D\xE9claration de classe typ\xE9e avec Dexie
